/* ===================== التحلل السكري ===================== */
module.exports['glycolysis']={sections:{},names:{},qs:[
 {type:'عرّف',tags:['2/1988','1/1992'],q:'عرّف التحلل السكري ؟',a:{p:'هي عملية تحول جزيئة سكر العنب ( سكر الكلوكوز ) هو مادة التنفس الرئيسة ، بعدما يعاني سلسلة من التفاعلات متحولاً إلى جزيئتين من الحامض البايروفي تجري في سايتوبلازم الخلية لوجود أنزيماتها .'}},
 {type:'علّل',tags:['3/2016 أسئلة خارج القطر','1/2025'],q:'تجري عمليات التحلل السكري في السايتوبلازم .',a:{p:'وذلك لوجود أنزيماتها في السايتوبلازم التي تساعد في التحلل السكري .'}},
 {type:'وضّح',tags:['2/2017 أسئلة خارج القطر'],q:'وضّح عملية التحلل السكري بإيجاز .',a:{p:'يمكن إيجاز عملية التحلل السكري بالآتي :',ol:['تنشيط جزيئة الكلوكوز ( 6C ) بالفسفرة فيتحول إلى كلوكوز أحادي الفوسفات ، وتستهلك في العملية جزيئة من ATP .','يتم تحويل الكلوكوز أحادي الفوسفات ( 6C ) إلى فركتوز أحادي الفوسفات ( 6C ) بفعل أنزيم معين .','يتم تنشيط الفركتوز أحادي الفوسفات ( 6C ) بعملية فسفرة ثانية فيتحول إلى فركتوز ثنائي الفوسفات وتستهلك في العملية جزيئة من ATP .','تنشطر جزيئة الفركتوز ثنائي الفوسفات ( 6C ) إلى جزيئتين من الكليسر الديهايد المفسفر ( 3C ) كمحصلة لهذا الانشطار .','تتحول كل جزيئة من الكليسر الديهايد المفسفر إلى جزيئة من الحامض البايروفي ( أي تصبح بالنتيجة جزيئتان من الحامض البايروفي ) ، علماً أنه يتم إنتاج أربع جزيئات من ATP من خلال عملية التحول ويستهلك منها جزيئتين في عمليتي الفسفرة وبالتالي يكون الربح 2ATP .','إذا كان التنفس لاهوائياً فيحصل للحامض البايروفي إما تخمر كحولي أو تخمر لبني في سايتوبلازم الخلية ، أما إذا كان التنفس هوائياً فيتحول الحامض البايروفي إلى جزيئة من ( أستيل كو - A ) الذي يدخل في تفاعلات بدورة تدعى دورة كريبس في مايتوكوندريا الخلية .']}},
 {type:'ارسم',tags:['2/1990','2/1995','1/1997','2/2011','1/2018 أسئلة خارج القطر'],q:'وضّح بمخطط دورة التحلل السكري .',a:{p:'كلوكوز ( 6C ) ← تنشيط ( فسفرة ) باستهلاك ATP ← كلوكوز أحادي الفوسفات ( 6C ) ← بفعل أنزيم معين ← فركتوز أحادي الفوسفات ( 6C ) ← تنشيط ( فسفرة ) باستهلاك ATP ← فركتوز ثنائي الفوسفات ( 6C ) ← انشطار ← كليسر الديهايد المفسفر ( 3C ) + فوسفات ثنائي هيدروكسي أسيتون ( 3C ) ← تحرير طاقة مقدارها 4ATP و 2 ( 2H ) ← 2 حامض البايروفي ( 3C ) . استهلاك طاقة مقدارها 2ATP ، والعملية تحدث في السايتوبلازم . ( شاهد المخطط بالمحاكاة )'}},
 {type:'علّل',tags:['1/2002','1/2015'],q:'تستهلك جزيئتان من ATP خلال عملية التحلل السكري .',a:{p:'لأن الجزيئة الأولى تستهلك لتنشيط جزيئة الكلوكوز بالفسفرة فيتحول إلى أحادي الفوسفات ، وتستهلك الجزيئة الثانية في تنشيط الفركتوز أحادي الفوسفات بعملية فسفرة ثانية فيتحول إلى فركتوز ثنائي الفوسفات .'}},
 {type:'املأ الفراغ',tags:['2015 تمهيدي'],q:'الطاقة الناتجة من التحلل السكري تساوي {2ATP} ومن دورة كريبس تساوي {12ATP} .'},
 {type:'املأ الفراغ',tags:['2019 تمهيدي'],q:'مقدار الطاقة المتحررة من دورة كريبس {12} وفي التحلل السكري {2} .'},
 {type:'املأ الفراغ',tags:[],q:'الناتج النهائي لعملية التحلل السكري تكوين جزيئتين من {الحامض البايروفي} وجزيئتين من {H₂ ( 2(2H) )} .'},
 {type:'التركيب الكيميائي',tags:['1/2010','2/2019'],q:'ما التركيب الكيميائي للحامض البايروفي ؟',a:{p:'CH₃-CO-COOH'}}
]};

